import{ax as e,A as p,aQ as t,z as s}from"./chunks/framework.BWRXlwpK.js";const i="/assets/image-3.BOf39pi0.png",d=JSON.parse('{"title":"安装","description":"","frontmatter":{},"headers":[],"relativePath":"webpack/webpack-insert.md","filePath":"webpack/webpack-insert.md"}'),n={name:"webpack/webpack-insert.md"};function o(c,a,l,r,k,b){return s(),p("div",null,a[0]||(a[0]=[t('<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><p>webpack是 基于模块化的打包工具</p><h2 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to &quot;特点&quot;">​</a></h2><p><strong>为前端工程化而生</strong>：webpack致力于解决前端工程化，特别是浏览器端工程化中遇到的问题，让开发者集中注意力编写业务代码，而把工程化过程中的问题全部交给webpack来处理</p><p><strong>简单易用</strong>：支持零配置，可以不用写任何一行额外的代码就使用webpack</p><p><strong>生态强大</strong>：webpack是非常灵活、可拓展的，webpack本身的功能并不多，但是它提供了一些可以扩展功能的机制，使得一些第三方库可以融于webpack中</p><p><strong>基于node.js</strong>：由于webpack在构建的过程中需要读取文件，因此它是运行在node环境中的</p><p><strong>基于模块化</strong>：webpack在构建过程中要分析依赖关系，方式是通过模块化导入语句进行分析，它支持各种模块化标准，包括但不限于CommonJS、ES6 Module</p><h2 id="安装-1" tabindex="-1">安装: <a class="header-anchor" href="#安装-1" aria-label="Permalink to &quot;安装:&quot;">​</a></h2><p><strong>webpack通过npm安装，它提供了两个包：</strong></p><ul><li>webpack：核心包，包含了webpack构建过程中要用到的所有api</li><li>webpack-cli：提供一个简单的cli命令，它调用了webpack核心包的api，来完成构建过程</li></ul><p><strong>安装方式：</strong></p><ul><li>全局安装：可以使用webpack命令，但是无法为不同项目对应不同的webpack版本</li><li>本地安装：推荐，每个项目都使用自己的webpack版本进行构建</li></ul><p>命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webpack-cli</span></span></code></pre></div><blockquote><p>安装webpack和webnpack-cli，-D表示是安装在开发环境，因为webpack不需要在生产环境部署。</p></blockquote><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h2><p><strong>webpack</strong>：使用这个命令webpack在默认情况下会读取src下文件进行打包，打包后会在工程的根目录生成dist文件夹存放打包后的文件,可以将这段命令写入package.json中方便管理</p><p><img src="'+i+'" alt="alt text"></p><p><strong>【&#39;mode&#39; option has not been set】？</strong></p><p>按照上面的方式打包，会出现这个红色字体，这是因为没有选择打包模式【开发模式/生产模式】,虽然出现了红色字体但是这时的打包依然是成功的，因为没有设置模式默认打出的包是生产模式。</p><ul><li>npx webpack --mode=development：开发模式打包</li><li>npx webpack --mode=production：生产模式打包</li></ul>',22)]))}const g=e(n,[["render",o]]);export{d as __pageData,g as default};
